    return (
        'def solve():\n'
        '    n = int(input().strip())\n'
        '    parents = []\n'
        '    while len(parents) < n - 1:\n'
        '        try:\n'
        '            line = input()\n'
        '        except EOFError:\n'
        '            break\n'
        '        if line:\n'
        '            parents.extend(map(int, line.split()))\n'
        '    parents = parents[:max(0, n - 1)]\n'
        '    depth = [0] * (n + 1)\n'
        '    parity = [0] * (n + 1)\n'
        '    parity[0] = 1\n'
        '    max_depth = 0\n'
        '    node = 2\n'
        '    for p in parents:\n'
        '        d = depth[p] + 1\n'
        '        depth[node] = d\n'
        '        parity[d] ^= 1\n'
        '        if d > max_depth:\n'
        '            max_depth = d\n'
        '        node += 1\n'
        '    print(sum(parity[:max_depth + 1]))\n'
        '\n'
        'solve()\n'
    )


